// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  let googleQuery = '';
  item.json.Email.split(',').forEach((email, i) => {
    googleQuery += i !== 0 ? ' OR ' : ''
    googleQuery += `from:${email} OR to:${ email }`

  })

  // Only search messages since the last successful sync for this account --
  // avoids re-fetching (and the sub-workflow re-logging) a client's entire
  // mailbox history on every run once they already have a conversation
  // sheet. A brand-new account has no last_synced_at yet, so it still gets
  // the full history, same as before this existed.
  const lastSyncedAt = item.json.last_synced_at;
  if (lastSyncedAt) {
    const d = new Date(lastSyncedAt);
    if (!isNaN(d.getTime())) {
      const gmailDate = `${d.getFullYear()}/${String(d.getMonth() + 1).padStart(2, '0')}/${String(d.getDate()).padStart(2, '0')}`;
      googleQuery += ` after:${gmailDate}`;
    }
  }
  item.json.googleQuery = googleQuery;
}

return $input.all();

