const items = $input.all();
const output = [];
const head_email = $input.first().json.Email
for (const item of items) {
  const json = item.json;

  // Split emails
  const emails = (json.Email || "")
    .split(',')
    .map(e => e.trim())
    .filter(Boolean);

  // Parse Platform safely -- this used to only ever see a JSON-array string
  // (e.g. '["gmail","outlook"]') because plain single-provider accounts
  // ("gmail" / "outlook" with no brackets) were routed down a separate,
  // now-removed path instead of reaching this node. Now every account comes
  // through here, so a plain string must also be accepted -- treated as a
  // single-element array, which the rest of this function already handles
  // correctly as the "one provider" case.
  let platforms = [];
  const rawPlatform = json.Platform;
  if (Array.isArray(rawPlatform)) {
    platforms = rawPlatform;
  } else {
    try {
      const parsed = JSON.parse(rawPlatform);
      platforms = Array.isArray(parsed) ? parsed : [parsed];
    } catch {
      platforms = rawPlatform ? [rawPlatform] : [];
    }
  }

  // ---- CASE 1: Single email, multiple platforms ----
  if (emails.length === 1 && platforms.length > 1) {
    for (const rawPlatform of platforms) {
      if (!rawPlatform) continue;
      // Normalize + validate the same way CASE 2 below already does --
      // this branch used to pass the raw array value straight through
      // unchecked, so anything other than an exact lowercase "gmail" or
      // "outlook" (e.g. "Gmail", a stray space) would silently fail the
      // downstream "Gmail or Outlook?" equality check and get routed to
      // Outlook regardless of what it actually was, with no error.
      const platform = String(rawPlatform).trim().toLowerCase();
      if (platform !== 'gmail' && platform !== 'outlook') continue;

      output.push({
        json: {
          ...json,
          Email: emails[0],
          mails:head_email,
          Platform: platform
        }
      });
    }
    continue;
  }

  // ---- CASE 2: Multiple emails (normal mapping) ----
  const gmailEmails = [];
  const outlookEmails = [];

  for (let i = 0; i < emails.length; i++) {
    const email = emails[i];
    const platform = platforms[i];

    if (!platform || platform === "None") continue;

    if (Array.isArray(platform)) {
      if (platform.includes("gmail")) gmailEmails.push(email);
      if (platform.includes("outlook")) outlookEmails.push(email);
    } else {
      if (platform === "gmail") gmailEmails.push(email);
      if (platform === "outlook") outlookEmails.push(email);
    }
  }

  if (gmailEmails.length) {
    output.push({
      json: {
        ...json,
         mails:head_email,
        Email: gmailEmails.join(','),
        Platform: "gmail"
      }
    });
  }

  if (outlookEmails.length) {
    output.push({
      json: {
        ...json,
        mails:head_email,
        Email: outlookEmails.join(','),
        Platform: "outlook"
      }
    });
  }

  // Neither branch matched anything for this account -- e.g. Platform is
  // blank/unset (a row that hasn't been classified yet). Returning zero
  // items here would silently kill the loop: n8n stops the whole branch
  // when a node produces no output, which breaks the loop-back into
  // "For Each Account" and stalls every account still queued after this
  // one, not just this one. Emit an explicit "unclassified" marker
  // instead so the next node can route it straight back to the loop.
  if (!gmailEmails.length && !outlookEmails.length) {
    output.push({ json: { ...json, mails: head_email, Platform: '' } });
  }
}

return output;

const items = $input.all();
const data = $('Build Gmail Search Query').item.json;
const row_number = data.row_number;
const querymail = data.mails;
const allMessages = [];

for (const item of items) {
  const messages = item.json.messages || [];
  const fromEmail = item.json.by_mail; // get sender for this batch

  messages.forEach(msg => {
    allMessages.push({
      ...msg,
      from_email: fromEmail, // attach sender to each message
    });
  });
}

return [
  {
    json: {
      row_number:row_number,
      querymail:querymail,
      resource: 'gmail',
      email: $input.first().json.to_mail,
      name: $input.first().json.Name,
      messages: allMessages
    }
  }
];

const items = $input.all();
if (!items.length) return [];

// Find gmail & outlook objects safely
const gmailItem = items.find(i => i.json.resource === 'gmail');
const outlookItem = items.find(i => i.json.resource === 'outlook');

// ------------------
// Merge base fields
// ------------------
const merged = {
  row_number: gmailItem?.json.row_number ?? outlookItem?.json.row_number,
  name: gmailItem?.json.name ?? outlookItem?.json.name,
  querymail: gmailItem?.json.querymail ?? outlookItem?.json.querymail,

  // Combined resource string
  resource: items.map(i => i.json.resource).join(','),

  gmail: gmailItem
    ? {
        email: gmailItem.json.email,
        messages: gmailItem.json.messages || []
      }
    : null,

  outlook: outlookItem
    ? {
        email: outlookItem.json.email,
        ids: outlookItem.json.ids || []
      }
    : null
};

// ------------------
// Email merge + dedup
// ------------------
const rawEmails = [
  merged.gmail?.email,
  merged.outlook?.email
].filter(Boolean);

const combinedEmails = [
  ...new Set(
    rawEmails
      .flatMap(e => e.split(','))
      .map(e => e.trim())
      .filter(Boolean)
  )
].join(',');

// ------------------
// Final output object
// ------------------
return [
  {
    json: {
      row_number: merged.row_number,
      name: merged.name,
      querymail: merged.querymail,
      resource: merged.resource,
      email: combinedEmails,
      gmail: merged.gmail,
      outlook: merged.outlook,
      // Three different Drive parent folders exist from before the single-
      // provider path was consolidated into this one: gmail-only clients,
      // outlook-only clients, and dual-provider clients each live under a
      // different parent. This used to be picked correctly for gmail-only /
      // outlook-only accounts by "Detect Email Provider", which got deleted
      // along with the rest of that path during the node-count cleanup --
      // leaving every account hardcoded to the dual-provider parent only,
      // so an existing single-provider client's folder was never found by
      // the reuse-or-create search (wrong parent), and a duplicate would
      // get created under the wrong location instead.
      folder_id: (merged.gmail && merged.outlook)
        ? "102oeld1yMYGMmWs2Od198HqO1KeVhv_n"   // dual-provider (combined) parent
        : merged.gmail
        ? "1-1EdTSWeoFPnbRa_hKdYsX4aMnqiQSSE"    // gmail-only parent
        : "1L5xu6tTaS6yZXbHpTrpE4IQ1xjV8G_J8"    // outlook-only parent
    }
  }
];

const items = $items('Combine Gmail & Outlook Per Client', 0);
const results = [];

for (const item of items) {
  const data = item.json;

  const base = {
    row_number: data.row_number,
    name: data.name,
  };

  // Gmail object
  if (data.gmail) {
    results.push({
      json: {
        ...base,
        resource: 'gmail',
        email: data.gmail.email,
        messages: data.gmail.messages
      }
    });
  }

  // Outlook object
  if (data.outlook) {
    results.push({
      json: {
        ...base,
        resource: 'outlook',
        email: data.outlook.email,
        ids: data.outlook.ids
      }
    });
  }
}

return results;

// Microsoft Graph does not allow combining $search (needed here to match
// "from OR to" across possibly multiple addresses in one query) with $filter
// (needed for a receivedDateTime range) in the same request -- confirmed
// against Graph's own docs, not guessed. toRecipients also isn't filterable
// via $filter at all, so switching to $filter would silently drop the "to"
// side of the match. So the date scoping happens here instead, client-side,
// after the (still full-history) search returns -- less efficient than a
// server-side date filter would be, but correct and doesn't lose "to"
// matches. A brand-new account has no last_synced_at yet, so nothing here
// gets filtered out for it -- same full-history behavior as before.
const data = $('❓ Gmail or Outlook?').first().json;
const rowdata = $('Build Outlook Search Query').item.json

const row_number = rowdata.row_number;
const querymail = rowdata.mails;

const lastSyncedAt = data.last_synced_at ? new Date(data.last_synced_at) : null;
const isNewEnough = (item) => {
  if (!lastSyncedAt || isNaN(lastSyncedAt.getTime())) return true;
  const ts = item.json.receivedDateTime || item.json.sentDateTime;
  if (!ts) return true;
  return new Date(ts) >= lastSyncedAt;
};

// get all incoming messages (current node input) in DESC order
const messages = [...$input.all()].filter(isNewEnough).reverse();

// extract only VALID ids
const ids = messages
  .map(item => item.json.id)
  .filter(id => id); // 🔥 removes null, undefined, empty

// 🚫 if no ids, return nothing
if (ids.length === 0) {
  return [];
}

// ✅ return only when ids exist
return [
  (() => {
    const result = {
      json: {
        row_number:row_number,
        querymail:querymail,
        resource: "outlook",
        email: data.Email,
        by_mail:"outlook",
        name: data.Name,
        ids,
      }
    };
    return result;
  })(),
];

const idsArr = $input.first().json.ids;

const sheet_id = $('📄 Conversation Sheet (Resolved)').item.json.spreadsheetId;
const mainf4_id = $('📁 Client Root Folder (Resolved)').item.json.id;
const subf5_id = $('📁 Attachments Subfolder (Resolved)').item.json.id;

const by_mail = $input.first().json.resource;
const row_number = $input.first().json.row_number;

return idsArr.map((id, i) => ({
  json: {
    id,
    row_number,
    by_mail,
    sheet_id,
    mainf4_id,
    subf5_id,
    index: i,
    // Must match Gmail's field names/casing exactly ('source' + capital
    // 'Processed') -- the queue sheet is shared and appended via
    // autoMapInputData, so a mismatched field name here creates a SEPARATE,
    // unused column instead of populating the one every processor's queue
    // filter actually reads (Processed = false AND source = email). This
    // previously left every Outlook-sourced queue row permanently
    // unmatched by that filter -- never picked up by any processor.
    source: 'email',
    Processed: false
  }
}));

// Get messages array from previous node
const messagesArr = $input.first().json.messages
const row_number = $input.first().json.row_number
// Get parent info
const sheet_id = $('📄 Conversation Sheet (Resolved)').item.json.spreadsheetId;
const mainf4_id = $('📁 Client Root Folder (Resolved)').item.json.id;
const subf5_id = $('📁 Attachments Subfolder (Resolved)').item.json.id;

// Map over messages array
return messagesArr.map((msg, index) => ({
  json: {
    id: msg.id,
    row_number:row_number,
    threadId: msg.threadId,  // include threadId if needed
    by_mail: msg.from_email,
    sheet_id,
    mainf4_id,
    subf5_id,
    index,
    source: 'email',
    Processed:false
  }
}));

// Match on the client's name only, not the trailing "<email1,email2>" suffix --
// the email list is recomputed fresh every run from whatever this run's Gmail/
// Outlook search actually turned up, so it can drift from what got baked into
// the real folder's name at creation time (a new alias appears, order shifts,
// etc.) and an exact full-string match would then never hit again, forcing a
// duplicate folder. The name is the stable identity; the email suffix isn't.
const expectedName = $('Combine Gmail & Outlook Per Client').item.json.name.toString().trim().toLowerCase();
const exact = $input.all().find(item => {
  const folderName = (item.json.name || '').toString().trim().toLowerCase();
  return folderName === expectedName || folderName.startsWith(expectedName + ' <');
});
return [exact || { json: { id: '', name: '' } }];

const expected = ('attachments').toString().trim().toLowerCase();
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === expected);
return [exact || { json: { id: '', name: '' } }];

const expected = "conversation";
const exact = $input.all().find(item => (item.json.name || '').toString().trim().toLowerCase() === expected);
if (!exact) return [{ json: { id: '', name: '', spreadsheetId: '' } }];
return [{ json: { ...exact.json, spreadsheetId: exact.json.id } }];
